from flask import Flask, jsonify

app = Flask(__name__)

# Dati di esempio
users = {
    '1': {'nome': 'Alice', 'email': 'alice@example.com'},
    '2': {'nome': 'Bob', 'email': 'bob@example.com'}
}

@app.route('/users', methods=['GET'])
def get_users():
    return jsonify(users)

@app.route('/users/<user_id>', methods=['GET'])
def get_user(user_id):
    user = users.get(user_id)
    if user is None:
        return jsonify({'error': 'Utente non trovato'}), 404
    return jsonify(user)

from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'email' not in data or 'password' not in data:
        return jsonify({'error': 'Email e password obbligatori'}), 400
    # In produzione: verifica password hashata, non in chiaro!
    return jsonify({'message': f'Benvenuto, {data["email"]}!'})
